CREATE DATABASE SCOPED CREDENTIAL SynapseCreds_dedicated
WITH
    IDENTITY = 'Managed Identity';

-- EXTERNAL DATA SOURCE

CREATE EXTERNAL DATA SOURCE raw_ext_source_dedicated
WITH
(
    LOCATION = 'https://sasynapsedemo.dfs.core.windows.net/raw',
    CREDENTIAL = SynapseCreds_dedicated
);

--DROP EXTERNAL FILE FORMAT PARQUET_FORMAT;
CREATE EXTERNAL FILE FORMAT PARQUET_FORMAT_DEDICATED
WITH
(
    FORMAT_TYPE = PARQUET,
    DATA_COMPRESSION = 'org.apache.hadoop.io.compress.SnappyCodec'
);
